CREATE TABLE `service_variations` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`service_id` BIGINT UNSIGNED NOT NULL,`name` VARCHAR(120) NOT NULL,`duration_minutes` SMALLINT UNSIGNED NOT NULL,`price_cents` BIGINT UNSIGNED NOT NULL DEFAULT 0,`sort_order` SMALLINT UNSIGNED NOT NULL DEFAULT 0,`active` BOOLEAN NOT NULL DEFAULT TRUE,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `service_variations_public_id_key` (`public_id`),UNIQUE INDEX `service_variations_service_id_name_key` (`service_id`,`name`),INDEX `service_variations_tenant_id_service_id_active_sort_order_idx` (`tenant_id`,`service_id`,`active`,`sort_order`),CONSTRAINT `service_variations_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `service_variations_service_id_fkey` FOREIGN KEY (`service_id`) REFERENCES `services`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
